    , grace_period_content
    , create_user
    , create_at
    , update_user
    , update_at
    , del_yn
    , note
) VALUES (
    #{appSeq}
    , #{officeSeq}
    , #{gracePeriodSeq}
    , #{gracePeriodContentCode}
    , #{createUser}
    , CURRENT_TIMESTAMP
    , #{updateUser}
    , CURRENT_TIMESTAMP
    , 'N'
    , #{note}
)

mapper.select:
